pub fn byFallback(env: *DotEnv.Loader, buf: *bun.PathBuffer, cwd: []const u8, out: *[]const u8) ?Editor {
            inline for (Editor.default_preference_list) |editor| {
                if (Editor.byPATHForEditor(env, editor, buf, cwd, out)) {
